       41:     xtiff *xt = XTIFFDIR(tif);
       42:     XTIFFDirectory *xd = &xt->xtif_dir;
       43:     int i, num;
       44: 
       45:     /* call the inherited method */
       46:     if (PARENT(xt, printdir))
       47:         (PARENT(xt, printdir))(tif, fd, flags);
