       56:      * will only print them out if the TIFFPRINT_MYMULTIDOUBLES
       57:      * flag is passed into the print method.
       58:      */
       59:     if (TIFFFieldSet(tif, FIELD_EXAMPLE_MULTI))
       60:     {
       61:         fprintf(fd, "  My Multi-Valued Doubles:");
       62:         if (flags & TIFFPRINT_MYMULTIDOUBLES)
